// Original interview exercises. Source references checked September 20, 2026.
const date = "2026-09-20";
const esc = (s) => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c]);
const posts = [];
const backlinks = [];
function add(slug, topic, description, summary, parent, source, sections, exercise, prompt) {
  backlinks.push([parent, slug, topic]);
  posts.push({slug, title:`${topic} | Cluegent`, h1:topic, description, summary,
    publishedDate:date, modifiedDate:date, authorityKicker:"Interview questions and worked practice",
    sources:source,
    bodyHtml:`<nav aria-label="On this page"><h2>On this page</h2><ul>${sections.map(([h],i)=>`<li><a href="#answer-${i}">${esc(h)}</a></li>`).join('')}<li><a href="#practice">Practice exercise</a></li></ul></nav>${sections.map(([h,p],i)=>`<section><h2 id="answer-${i}" style="scroll-margin-top:110px">${esc(h)}</h2>${p.split('\n\n').map(t=>`<p>${esc(t)}</p>`).join('')}</section>`).join('')}<section><h2 id="practice" style="scroll-margin-top:110px">Practice exercise</h2>${exercise.split('\n\n').map(t=>`<p>${esc(t)}</p>`).join('')}</section><section><h2>Rehearse this answer with Cluegent</h2><p>${esc(prompt)}</p><p><a href="/download/">Try Cluegent for your practice session</a>, then repeat the explanation without suggestions. Judge your answer by its accuracy, evidence, and response to follow-up questions.</p></section>`,
    faqs:[{q:`How should I practise this topic?`,a:exercise.split('\n\n')[0]},{q:"How can Cluegent help with preparation?",a:prompt}],
    links:[[ `/blog/${parent}/`,"Continue with the broader interview guide"],["/blog/mock-interview-with-ai/","Build a repeatable mock interview"],["/download/","Download Cluegent"]],
  });
}

add("typescript-interview-questions","TypeScript Interview Questions with Practical Answers",
  "Prepare TypeScript interview answers on unknown, narrowing, discriminated unions, generics, and runtime validation with an API response exercise.",
  "TypeScript helps describe valid program states before execution. Strong interview answers also explain the boundary between compile-time checks and data that arrives at runtime.",
  "javascript-coding-interview-questions",[["https://www.typescriptlang.org/docs/handbook/2/narrowing.html","TypeScript handbook: narrowing"]],[
  ["When should you use unknown instead of any?","Use unknown when a value exists but its shape has not been established. You must narrow it before accessing properties. Any permits operations without those checks and can allow an incorrect assumption to spread. Neither keyword validates incoming JSON by itself.\n\nFor a payment response, first establish that the payload is an object, then validate the fields the application requires. An assertion that labels the payload as Payment only changes what the compiler accepts. Explain what happens if the server sends a string where your application expects an amount."],
  ["How does a discriminated union improve state modeling?","Give each alternative a distinct literal field, such as status: loading, success, or error. Associate the result with success and the error message with error. Narrowing on status lets the code access the appropriate fields. This prevents a loose collection of optional properties from admitting contradictory combinations.\n\nIn our dashboard example, success requires an account object. Loading cannot accidentally display an old account as a newly completed result. Discuss whether stale cached data deserves its own explicit state rather than overloading success with hidden assumptions."],
  ["What problem should a generic solve?","A generic preserves a relationship between types. A function that returns the first element of an array should retain the element type, while accounting for an empty array. Replacing every type with a generic parameter does not automatically improve an API.\n\nExplain the caller's benefit: passing an array of users yields a user or an absent result, rather than an unrelated unknown value. Then describe the runtime empty-array behavior. The interviewer should be able to understand both the type relationship and the execution contract."],
  ["How would you investigate a type assertion hiding a bug?","Trace where untrusted data enters and where the assertion bypasses a check. Reproduce with a small payload that violates the expected shape. Move validation to that boundary and define a useful failure result. Avoid scattering assertions through components to silence errors caused by an unclear contract.\n\nFor a practical follow-up, make the amount optional upstream. Decide whether absence is a valid business state, a defaultable value, or an error. Encode that decision and test it. A compiler error can reveal a missing product decision rather than merely inconvenient syntax."],
],"Model a request with loading, success, and error states. Write one valid example of each, then try constructing success without its result. Explain which mistakes the compiler should catch and which require runtime validation.\n\nNext, receive an unknown JSON payload and describe the checks needed before creating the success state. Include null, an empty object, a wrong field type, and an extra harmless field. Keep the exercise small enough to explain in five minutes.","Paste your proposed state model into Cluegent during preparation and ask: 'Which impossible states does this still permit, and which inputs require runtime validation?' Explain the revised model aloud.");

add("git-interview-questions","Git Interview Questions: Branches, Conflicts, and Recovery",
  "Practise Git interview questions about merge versus rebase, revert, conflict resolution, and recovering from a faulty shared commit with a concrete scenario.",
  "Git interview questions are easier when you distinguish the working files, staging area, commit history, and shared branch. Explain the intended result before choosing a command.",
  "ci-cd-interview-questions",[["https://git-scm.com/docs/git-revert","Git documentation: revert"]],[
  ["What is the difference between a working tree and a commit?","The working tree contains the files you are editing. The index records what is staged for the next commit. A commit records a snapshot with history information. Editing a file after staging it can leave one version staged and a newer version in the working tree.\n\nOur exercise changes a configuration value, stages it, then edits a comment in the same file. Explain why the next commit may omit that comment. Review the staged difference when describing exactly what a commit will contain."],
  ["When would you merge rather than rebase?","A merge combines histories while retaining the existing commits. Rebasing replays changes onto another base and creates new commit identities. The practical decision depends on whether others already depend on the branch and on the team's collaboration convention.\n\nImagine a feature branch used by three developers. Rewriting it without coordination can leave collaborators working from different histories. Explain how you would update your branch and resolve conflicts while preserving their work. There is no universally best history shape for every team."],
  ["How does revert help undo a shared change?","Git revert records a new commit that reverses the effect of an earlier change. It is useful when the original commit is already part of shared history. Reverting code does not automatically reverse a database migration, an external payment, or another side effect produced by a deployment.\n\nIn an interview, describe both repository recovery and application recovery. If the commit removed a field that a newer release already relies on, a blind revert may create another incompatibility. Inspect dependent changes and define the behavior you want restored."],
  ["How do you resolve a conflict correctly?","Read both changes and the surrounding behavior, then decide what the final program should do. Accepting one side mechanically can discard a valid fix from the other side. Resolve the file, inspect the resulting difference, and run the relevant checks.\n\nSuppose one branch renames a function while another adds validation inside it. The correct resolution may combine the new name with the validation. Explain why removing conflict markers proves only that the file is syntactically merged, not that the intended behavior survived."],
],"Draw a shared main branch with commits A, B, and C. B introduces a bug; C adds a useful feature that depends on part of B. Describe a recovery that keeps C working, and explain what you would verify before publishing it.\n\nRepeat with an uncommitted local edit present. Identify what must be preserved before any history operation. The strongest answer separates recovering code, coordinating with teammates, and verifying the deployed behavior.","Ask Cluegent to challenge your recovery plan with a dependent commit or an uncommitted file. Practise explaining the consequences of each operation before suggesting commands.");

add("linux-interview-questions","Linux Interview Questions: Diagnose CPU, Disk, and Permissions",
  "Prepare Linux troubleshooting interview answers with process, disk-space, permissions, log, and networking scenarios plus an evidence-first incident exercise.",
  "A useful Linux answer connects a symptom to evidence. These questions focus on investigating a service that is slow, unable to write, or unreachable without making random configuration changes.",
  "sre-interview-questions",[["https://www.gnu.org/software/coreutils/manual/coreutils.html","GNU Coreutils reference"]],[
  ["A process is slow. What would you inspect first?","Clarify whether the delay is new, which requests are affected, and whether the process is using CPU or waiting on something else. Compare process activity with dependency latency and the incident timeline. High load alone does not prove that more CPU will solve the problem.\n\nFor our example, a report job slows an API only during business hours. Compare report volume, concurrent requests, and resource contention. State what observation would distinguish expensive computation from storage waiting or an overloaded database."],
  ["How can a write fail when a directory looks small?","Inspect the filesystem that actually contains the destination, available space, inode availability, and the process's permissions. A directory listing does not describe every consumer of that filesystem. Also consider an open deleted file still held by a running process.\n\nImagine a log writer failing after a large deployment. First identify its destination and the filesystem boundary. Do not remove arbitrary files to create space. Explain how you would locate the relevant usage, preserve necessary evidence, and verify that the application can write again."],
  ["Why might a file permission change not fix access?","Access depends on the process identity and the path leading to the file, as well as the file's permissions. Directory traversal and deployment ownership can matter. Establish the effective user and the actual path before deciding what permission needs changing.\n\nOur sample service reads a configuration file through a directory accessible only to its owner. Changing the file's read bit alone leaves the directory boundary intact. Explain the narrow intended access and avoid treating world-writable permissions as a general repair."],
  ["How would you debug an unreachable service?","Trace name resolution, destination address, listening socket, network path, and application response. A process can be running without listening on the expected interface. A successful request from the server itself may not establish reachability from a remote client.\n\nState where each test originates. If localhost succeeds but a remote connection fails, investigate the listener binding and network controls before rewriting application logic. Keep request timeouts distinct from connection failures and explain which evidence narrows the next step."],
],"Rehearse a service that returns errors after a deployment. You learn that reads work, writes fail, and CPU is normal. List three competing causes, the smallest read-only observation for each, and the correction each result would justify.\n\nFinish with a recovery check from the affected user's path. Record the cause, the verified repair, and a monitoring signal that would catch recurrence. A list of commands is less useful than a sequence that explains why each command is needed.","Give Cluegent the symptoms one at a time and ask it to act as a mock interviewer. State your hypothesis before requesting another clue, then revise it when the evidence changes.");

add("terraform-interview-questions","Terraform Interview Questions: State, Plans, and Drift",
  "Practise Terraform interview questions on state, plan review, drift, modules, and team workflows with a production replacement-risk exercise.",
  "Terraform interviews test whether you can manage infrastructure changes predictably. Start with the relationship between configuration, recorded state, and the resources that exist in the provider.",
  "devops-engineer-interview-questions",[["https://developer.hashicorp.com/terraform/language/state","HashiCorp: Terraform state"]],[
  ["What is Terraform state used for?","State records Terraform's mapping between configured resource instances and remote objects, along with information needed to manage them. It is part of the operational workflow rather than a disposable cache. Losing that mapping can make subsequent changes difficult to reason about.\n\nFor our example, a bucket exists in the cloud, but a newly configured workspace has no association with it. Explain why matching a human-readable name does not automatically establish management. Distinguish importing an existing object from creating a new one."],
  ["What should you inspect in a plan?","Look for unexpected creation, deletion, replacement, and changes to identifiers or dependencies. Compare the proposed actions with the requested business change. A plan with no syntax error can still describe the wrong environment or a destructive replacement.\n\nSuppose a small naming cleanup unexpectedly replaces a database. Stop to understand whether the attribute is immutable, the address changed, or the selected state is wrong. The review should explain why replacement is necessary before considering how to schedule it."],
  ["What is drift, and how do you handle it?","Drift is a difference between the configuration's intended management and changes made to the actual infrastructure outside the expected workflow. Investigate who changed what and why. Decide whether the configuration should adopt the change or the infrastructure should return to the intended state.\n\nAn emergency firewall change may have been necessary during an incident. Automatically undoing it can recreate the incident, while permanently leaving it undocumented creates another problem. Reconcile the operational intent and preserve a reviewable explanation of the final configuration."],
  ["How should a team organize state and modules?","Separate environments and ownership boundaries deliberately, with appropriate access controls and coordination for changes. Backend capabilities vary, so verify locking and recovery behavior for the selected backend. Modules should expose a useful contract rather than simply hide a large collection of unrelated resources.\n\nFor a shared network module, identify which inputs callers own, which outputs they need, and how a version change affects dependent stacks. Keep a rollback or recovery story for a failed change. A module's reuse is valuable only if its behavior remains understandable."],
],"Review a hypothetical plan that adds one tag but replaces a database and removes a network rule. Write the questions you would ask before applying it. Include selected environment, resource addresses, provider changes, and dependencies.\n\nThen describe how you would test the intended change in a representative non-production environment. Do not claim that every infrastructure change can be rolled back by applying the previous configuration; data and external effects need their own recovery plan.","Use Cluegent to rehearse a plan-review discussion. Ask for one unexpected replacement scenario, then explain the evidence needed before approving the infrastructure change.");

add("sql-window-functions-interview-questions","SQL Window Functions Interview Questions with Examples",
  "Learn SQL window-function interview answers for ranking, running totals, LAG, ties, and frames using a small dataset with expected results.",
  "Window functions calculate across related rows while retaining individual rows. Interviewers can test both the result and whether you understand ordering, ties, and the rows included in a calculation.",
  "sql-interview-questions",[["https://www.postgresql.org/docs/current/tutorial-window.html","PostgreSQL: window functions"]],[
  ["How is a window function different from GROUP BY?","Grouping typically combines rows into one row per group. A window calculation can attach a group-level or ordered calculation to each original row. Choose based on the output grain the report needs.\n\nImagine three orders worth 20, 30, and 10 for one customer. A grouped sum produces one total of 60. A window sum can show 60 beside each order, preserving all three order identities. Explain why that repeated total should not subsequently be summed as though it represented three independent amounts."],
  ["How do ROW_NUMBER, RANK, and DENSE_RANK handle ties?","ROW_NUMBER gives each row a distinct sequence number. RANK leaves gaps after ties, while DENSE_RANK does not. State the tie policy before choosing one. Add a deterministic tiebreaker when distinct ordering is required.\n\nFor scores 90, 90, and 80 ordered descending, ranks are 1, 1, 3 and dense ranks are 1, 1, 2. Row numbers are 1, 2, 3, but which tied candidate gets the first number requires another ordering key. This distinction matters when 'top two' means two rows versus two score levels."],
  ["What makes a running total predictable?","Specify the partition, the ordering, and the intended frame. For an order-by-order running total, an explicit row frame from the beginning through the current row makes the intent clear. Include a unique ordering key when timestamps can tie.\n\nWith orders numbered 1, 2, and 3 and amounts 20, 30, and 10, the expected totals are 20, 50, and 60. Change two timestamps to the same value and explain whether your chosen calculation should move one row at a time or treat peers together."],
  ["When would you use LAG?","LAG retrieves a preceding value within the chosen partition and order. It can support comparisons with the previous recorded observation. It does not automatically mean the previous calendar day when dates are missing.\n\nOur metric has records on Monday and Wednesday. Wednesday's previous row is Monday. If the report asks for a day-over-day comparison, decide how Tuesday's missing observation should be represented. Creating a date series or defining missing-data rules may be necessary before calculating the difference."],
],"Use amounts 20, 30, and 10 with unique order IDs. Predict the grouped total, total attached to each row, running total, and previous amount. The first previous amount should be absent unless you intentionally supply a default.\n\nAdd a second customer and repeat the calculation. Every customer's sequence should restart. Then add tied scores and explain the difference between selecting two rows and selecting the highest two distinct score levels.","Ask Cluegent to generate a follow-up with tied timestamps or a missing date. Write the expected rows by hand before checking the SQL so you can explain the semantics confidently.");

add("postgresql-index-interview-questions","PostgreSQL Index Interview Questions and Query Plans",
  "Practise PostgreSQL indexing interview answers with selective filters, composite indexes, EXPLAIN, estimate errors, and a slow orders-query exercise.",
  "An index is useful when it helps the database retrieve the required rows economically. Strong answers connect a query's predicates, ordering, and data distribution to a measured plan.",
  "data-engineer-interview-questions",[["https://www.postgresql.org/docs/current/using-explain.html","PostgreSQL: interpreting EXPLAIN"]],[
  ["Why might PostgreSQL ignore an index?","An index is an available access path, not an instruction that every query must use it. A sequential scan may be reasonable when many rows are needed or a table is small. Inspect the chosen plan and representative data before assuming the planner made a mistake.\n\nIn our example, almost every order is marked completed. An index on status may help a rare status query more than the common completed query. Explain selectivity in terms of the rows required, not merely the presence of a WHERE clause."],
  ["How would you choose a composite index?","Start with the real query: filters, join conditions, ordering, and result limit. Column order and operator behavior matter. Consider the specific index type and workload rather than applying a universal rule such as indexing every filtered column separately.\n\nFor an orders screen that filters by customer and displays the newest entries, evaluate an index beginning with customer identity and supporting the desired ordering. Then test a large customer and a small customer. One convenient sample cannot represent all distributions."],
  ["What does EXPLAIN ANALYZE add?","EXPLAIN describes the planner's estimate. EXPLAIN ANALYZE executes the statement and reports observed execution information, so use care with statements that change data. Compare estimated and actual row counts as well as time. Planner cost values are not elapsed milliseconds.\n\nA large estimate mismatch can direct attention to statistics or an assumption about correlated data. A slow query can also spend time outside the database plan, such as transferring an enormous result. Explain which portion of the user's latency your measurement actually covers."],
  ["What does an index cost the system?","Indexes consume storage and must be maintained as data changes. More indexes can increase write work and complicate operational maintenance. Evaluate the benefit across the workload rather than optimizing one read in isolation.\n\nSuppose an audit table receives frequent inserts but is rarely queried interactively. A speculative collection of indexes may be less valuable than a narrowly justified access path. State the relevant read frequency, write volume, and retention needs before deciding what to add."],
],"Take a query for the newest twenty orders belonging to one customer. Describe a baseline measurement, a candidate index, and the result that would justify keeping it. Verify the returned rows remain identical.\n\nRepeat with an unusually large customer and with a filter matching most of the table. Record plan changes and write overhead. Finish with a short explanation of why the index helps a particular workload instead of claiming that indexes always make SQL faster.","Paste a sanitized query plan into Cluegent during preparation and ask which estimate or access path deserves investigation. Check its interpretation against PostgreSQL documentation and your measured results.");

add("redis-interview-questions","Redis Interview Questions: Caching, Expiry, and Failures",
  "Prepare Redis interview answers on cache-aside, TTL, stale data, cache stampedes, memory pressure, and database protection through a product-page scenario.",
  "Redis interview questions often become architecture questions. Define whether Redis holds disposable cached data or business state before discussing expiry, recovery, and availability.",
  "system-design-interview-questions-beginners",[["https://redis.io/docs/latest/develop/using-commands/keyspace/","Redis: keys and expiration"]],[
  ["How does cache-aside work?","The application checks the cache, loads a missing value from the source of truth, and stores the result for later reads. Explain the miss path as carefully as the hit path. A cache that is excellent when warm can still overload the database after a restart.\n\nOur product page caches a description and display price. Decide which fields may tolerate temporary staleness. A cached display value should not silently become the authoritative amount charged at checkout unless the business contract explicitly supports that behavior."],
  ["How should you choose a TTL?","A time-to-live bounds how long an entry remains usable under its expiration policy, but it is not a complete consistency strategy. Choose it from acceptable staleness, update frequency, and the cost of rebuilding a value. Different data may deserve different policies.\n\nFor a product title, a short delay after an edit may be acceptable. For inventory allocation, stale state can cause a different class of error. Explain the operation's correctness requirements before choosing a convenient number of minutes for every key."],
  ["What is a cache stampede?","When many requests discover the same missing or expired value, they can all query the underlying system. Coalescing concurrent refreshes, spreading expiration times, and carefully serving stale data where permitted can reduce that burst. Each technique needs an explicit failure policy.\n\nImagine a popular product whose cached entry expires during a campaign. A thousand simultaneous rebuilds are wasteful. Explain who performs refresh, how long others wait, and what happens if refresh fails. Avoid turning one slow refresher into an indefinite wait for every request."],
  ["What should happen when Redis is unavailable?","Decide whether a bounded fallback to the source is safe, whether some functionality should degrade, or whether the operation must fail. Sending the full cached workload directly to a smaller database can create a cascading outage. Recovery behavior belongs in the design from the beginning.\n\nMemory pressure and eviction also matter: a cache entry can disappear before your application expects. If the value is essential business state, describe persistence and recovery requirements separately. Calling a store fast does not establish its durability guarantees."],
],"Design the product-page cache for normal traffic and a sudden burst. Write the hit, miss, refresh-failure, and cache-unavailable paths. For each path, identify the maximum work allowed against the database.\n\nChange the cached value from a description to a one-time redemption token. Explain why the correctness and recovery requirements change. This follow-up reveals whether your design depends on assumptions you have actually stated.","Use Cluegent to challenge your caching design with an expired hot key or an unavailable cache. Practise describing the fallback limits and the tradeoff between freshness and availability.");

add("microservices-interview-questions","Microservices Interview Questions with Failure Scenarios",
  "Practise microservices interview questions on service boundaries, synchronous calls, messages, duplicate events, and order-workflow failures with worked reasoning.",
  "Microservices introduce independent deployment and distributed failure. Interview answers should explain why a boundary is useful and how the system behaves when only part of a workflow succeeds.",
  "system-design-mock-interview-with-ai",[["https://learn.microsoft.com/en-us/azure/architecture/microservices/design/interservice-communication","Microsoft: communication between services"]],[
  ["When is a separate service justified?","Consider ownership, independent change, scaling requirements, and a stable business boundary. Splitting every database table into a service can increase coordination without creating useful independence. A modular application can be a reasonable starting point when the team and workload do not need distribution.\n\nFor our order example, payments have a different reliability and integration boundary from catalog browsing. Explain what each service owns and which contract connects them. If every small change still requires a coordinated deployment, examine whether the boundary is helping."],
  ["When would you choose a message over a direct call?","A direct call can provide an immediate response, but the caller depends on the callee's availability and latency. Messaging can decouple work in time, while introducing delivery, ordering, backlog, and observability concerns. Choose based on what the user must know immediately.\n\nAn order confirmation email may run after order acceptance. Payment authorization may need a different user-visible state. Do not label an entire system asynchronous without tracing the exact moment when the customer sees success and what that success promises."],
  ["How do you handle duplicate events?","Assume a delivery mechanism may repeat a message unless its contract establishes otherwise. Give the consumer a way to recognize already handled work and protect the relevant state transition. Deduplicating a log entry is easier than preventing a duplicate external charge.\n\nIn our exercise, the same payment-confirmed event arrives twice. The order should not be shipped twice. Explain how event identity, transaction boundaries, and the shipment operation interact. A claim of exactly-once delivery does not automatically establish exactly-once business effects across every dependency."],
  ["How do you investigate a partially completed order?","Trace a correlation identifier through the workflow and inspect durable state transitions. Distinguish waiting, failure, retry, and manual intervention states. A single red error message may not tell you whether an external operation completed before its response was lost.\n\nIf payment succeeded but inventory reservation failed, define the intended recovery: another reservation attempt, a different fulfillment path, or compensation. State who owns that decision and how the user sees the outcome. Compensation can itself fail and needs visibility."],
],"Draw a workflow containing order creation, inventory reservation, payment, and shipping. Introduce a failure after each step and describe the durable state left behind. Identify which operations can be retried safely and which require an idempotency contract.\n\nNow add a duplicated event and a delayed event. Explain the allowed state transitions and how support staff identify a stuck order. A complete answer includes operations and recovery, not only boxes and arrows.","Ask Cluegent to play the interviewer and interrupt your order-flow explanation with one dependency failure. Rehearse a response covering user impact, state, retry safety, and recovery ownership.");

add("rest-api-interview-questions","REST API Interview Questions: Methods and Resource Design",
  "Prepare REST API interview answers on resources, HTTP methods, idempotency, status codes, pagination, and backward compatibility with an order API exercise.",
  "A strong API design answer describes a predictable contract for callers. Focus on resource meaning, retry behavior, errors, and evolution rather than treating REST as a URL naming contest.",
  "api-testing-interview-questions",[["https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Methods","MDN: HTTP request methods"]],[
  ["How do you choose resource boundaries?","Model the entities and operations that callers need to understand. For an order API, distinguish creating an order, retrieving its status, and requesting cancellation. Do not expose an internal database structure merely because it is convenient for the server implementation.\n\nExplain what an order identifier refers to and which fields are stable. If cancellation is a request that can be refused after shipping, reflect that lifecycle in the contract. A successful network request should not misleadingly imply that every requested business action has finished."],
  ["What is idempotency?","An idempotent method has the same intended effect when repeated as when performed once. Responses can still differ between attempts. HTTP method semantics provide expectations, but the application must implement its contract correctly. POST creation commonly needs an additional mechanism when clients may retry after ambiguous failures.\n\nFor our example, a client times out after creating an order. A request identity can let the server associate a retry with the original operation. Define retention and conflicting-payload behavior rather than assuming that adding an arbitrary header solves duplicate creation."],
  ["How should errors help a client recover?","Use the documented status and a stable error structure that distinguishes invalid input, missing resources, permission problems, and transient failures where appropriate. Include enough context for correction without exposing internal credentials or private records.\n\nSuppose quantity exceeds the available stock. The client needs an actionable business error, not a stack trace. Explain whether it should refresh availability, let the user change quantity, or stop retrying. An error contract is part of the product experience."],
  ["How do pagination and compatibility affect API design?","Define ordering and the effect of records changing between page requests. A cursor and an offset have different operational properties; neither removes the need to describe consistency. Provide bounded page sizes so one caller cannot accidentally request an enormous response.\n\nFor compatibility, distinguish adding optional information from changing the meaning or type of an existing field. Test known clients against contract changes. Versioning can help manage change, but it does not excuse unclear deprecation or migration behavior."],
],"Design an order API with create, read, list, and cancel operations. For each, write the request, expected state change, successful response, and one failure response. Add a repeated create request and a cancellation after shipping.\n\nThen explain how a mobile client behaves after losing a response. State what it can safely retry and how it finds the final operation status. This reveals ambiguities that are easy to miss when designing only the happy path.","Paste your API contract into Cluegent during preparation and ask for a client-retry counterexample. Check the proposed behavior against your intended HTTP and business semantics.");

add("python-asyncio-interview-questions","Python Asyncio Interview Questions with Practical Scenarios",
  "Practise Python asyncio interview answers on coroutines, tasks, blocking calls, bounded concurrency, cancellation, and timeouts with a batch-download exercise.",
  "Asyncio helps coordinate concurrent waiting, but it does not make every operation parallel. Interview answers should describe when work runs, when it yields, and how failures stop or affect related work.",
  "python-interview-questions",[["https://docs.python.org/3/library/asyncio-task.html","Python: coroutines and tasks"]],[
  ["Does calling an async function run it to completion?","Calling a coroutine function creates a coroutine object. It must be awaited or scheduled appropriately to execute. Explain this distinction before discussing speed: writing async def alone does not create a background worker or guarantee concurrent execution.\n\nFor our practice example, create two independent fetch operations. Awaiting one before starting the other can serialize their waits. Scheduling appropriate concurrent work can overlap the waits, provided the libraries cooperate with the event loop."],
  ["Why can a blocking call freeze other tasks?","A synchronous operation that occupies the event-loop thread prevents other tasks on that loop from making progress during that time. Identify blocking file, network, or CPU work rather than assuming every call inside an async function cooperates.\n\nImagine an endpoint that fetches data asynchronously and then performs a large CPU transformation. Other requests can still suffer during that transformation. Explain whether to reduce the work, use an appropriate executor, or change the design; the correct choice depends on workload and library behavior."],
  ["How do you prevent too much concurrent work?","Use a bounded design such as a fixed worker pool or semaphore around the constrained operation. Also consider queued input size: limiting active requests does not by itself limit the memory occupied by millions of waiting tasks.\n\nOur exercise downloads metadata for many records. Specify a bound on active connections and a bound on pending work. Explain how the producer slows down when the queue fills and how cancellation stops further input. A large concurrency value is not evidence of a fast or stable system."],
  ["What should happen when one task fails?","Choose a failure policy that matches the operation. Some batches should stop together; others should return independent successes and failures. Python's task-management tools have specific propagation and cancellation behavior, so describe the tool you use rather than treating all combinations as equivalent.\n\nA timed-out request still needs resource cleanup. Avoid swallowing cancellation in a broad recovery path. Explain how connections close, what happens to incomplete results, and which work may safely be retried. The caller should receive a clear outcome instead of a permanently pending batch."],
],"Describe a metadata downloader with twenty inputs, at most three in-flight requests, a per-request deadline, and a maximum overall duration. Decide whether one failed record should cancel the remaining records or be reported independently.\n\nTest a slow response, an immediate failure, cancellation halfway through, and an empty input. Track the peak number of active operations to verify the concurrency limit. Explain why the result order may need explicit handling.","Ask Cluegent to challenge your downloader with a blocking library call or cancellation during cleanup. Rehearse how the event loop, queue, and caller each observe the failure.");

add("unit-testing-interview-questions","Unit Testing Interview Questions: Boundaries and Mocks",
  "Prepare unit testing interview answers about test boundaries, mocks, edge cases, coverage, and deterministic design with an original delivery-fee exercise.",
  "Useful unit tests make incorrect behavior visible with a small, repeatable example. Explain what a test proves and which integration risks remain outside its scope.",
  "automation-testing-interview-questions",[["https://docs.python.org/3/library/unittest.html","Python: unit testing framework"]],[
  ["What makes a unit test useful?","Choose a clear behavior, controlled inputs, and an observable expected result. A test should fail when that behavior breaks and provide enough context to locate the problem. Whether the unit is a function or a small component depends on the design.\n\nFor a delivery-fee function, test the business boundary rather than how many private helper functions it calls. Refactoring an internal helper should not force unrelated tests to change if the externally meaningful behavior remains correct."],
  ["How do you choose edge cases?","Partition inputs by rules, then test boundaries and representative cases. Our sample policy charges 50 for orders below 500 and zero at or above 500, with negative order amounts rejected. Useful inputs include 0, 499, 500, and a negative amount.\n\nSpecify the numeric unit and valid type. If the amount is represented in minor currency units, the threshold must use the same unit. A mathematically correct comparison using inconsistent units is still a business defect. Tests should make that assumption visible."],
  ["When should you mock a dependency?","Mock when you need a controlled substitute for a boundary such as a clock or external service. Keep assertions focused on the contract that matters. Over-mocking internal collaborators can make tests pass while the real components no longer work together.\n\nIf a delivery quote depends on a remote carrier, unit tests can exercise success and timeout handling using a substitute. Retain an appropriate integration check for the actual request and response contract. A mock returning an invented shape cannot establish compatibility with the real service."],
  ["Does high coverage prove correctness?","Coverage describes exercised code, not the strength of the assertions or completeness of requirements. A test that calls a function and checks nothing can execute many lines. Use coverage to find unexamined paths, then evaluate whether important behavior is meaningfully asserted.\n\nDeterminism also matters. Inject a clock or controlled random source when the behavior depends on time or randomness. Avoid a test that passes only before midnight or only with the developer's timezone. State which environment assumptions the test owns."],
],"Write expected results for delivery fees at 0, 499, 500, and 501, plus rejection for a negative amount. Change the implementation's threshold comparison from greater-than-or-equal to greater-than and identify the test that must fail.\n\nNext, add a loyalty exemption. Test the interaction between loyalty and invalid input, and decide which rule wins. This is a requirements question before it is a testing-framework question. Keep the expected results explicit.","Use Cluegent to propose a mutation that should break your delivery-fee tests. Check whether the suite catches it, then explain any uncovered rule in your own words.");

add("binary-search-interview-questions","Binary Search Interview Questions: Boundaries and Duplicates",
  "Practise binary search interview questions using invariants, lower bounds, duplicate values, missing targets, and a worked trace with expected positions.",
  "Binary search is about discarding a region that cannot contain the answer. A clear invariant and boundary convention matter more than memorizing a loop that almost works.",
  "how-to-prepare-for-coding-interview-in-7-days",[["https://docs.python.org/3/library/bisect.html","Python: bisection and insertion positions"]],[
  ["What must be true before binary search applies?","You need an ordered search space or a monotonic condition that lets you discard one side safely. A sorted array is the familiar case, but the underlying requirement is the decision boundary. State that assumption explicitly rather than silently searching arbitrary input.\n\nFor our exercise, the array is 2, 4, 4, 7, 9 in ascending order. Decide whether the desired result is any matching position, the first matching position, or an insertion point. Those are different contracts when duplicates exist."],
  ["What is a lower bound?","A lower bound is the first position whose value is at least the target, or the end position if none exists. Python's bisect_left provides this insertion-position behavior. It does not prove the target itself is present.\n\nFor the sample array, target 4 has lower bound 1 using zero-based indexing. Target 5 has lower bound 3, even though 5 is absent. To turn that result into membership, check that the position is within the array and that its value equals the target."],
  ["How do you explain loop boundaries?","Choose either a closed interval or a half-open interval and keep every update consistent with it. For a half-open interval, the right boundary is excluded. Each iteration must shrink the remaining region while preserving every possible answer.\n\nTrace a two-element input to catch mistakes that a large example hides. If an update assigns a boundary to the same position repeatedly, the loop may never terminate. Explain why the chosen midpoint and update guarantee progress, including when the target falls before the first or after the last element."],
  ["Why is a logarithmic search not always the whole complexity?","The search may take logarithmic comparisons while another operation dominates. Inserting into the middle of an array can require moving many elements. Sorting an unsorted input first also adds work that a simple search-complexity claim omits.\n\nIf the interviewer asks about repeated queries, compare paying a preparation cost once against scanning for each query. Include update frequency and memory constraints. The useful answer describes the complete workload, not just the most impressive subroutine."],
],"Trace lower-bound positions for targets 1, 4, 5, and 10 in [2, 4, 4, 7, 9]. The expected positions are 0, 1, 3, and 5. Check membership separately: only target 4 exists.\n\nRepeat on an empty array, one element, and an array where every element equals the target. Explain the invariant before writing code, then show that every iteration reduces the remaining interval. Use these cases to catch off-by-one errors.","Ask Cluegent to challenge your binary-search explanation with duplicates or an empty input. Predict the result and trace the boundaries before checking generated code.");

add("panel-interview-preparation","Panel Interview Preparation: Questions and Answer Strategy",
  "Prepare for a panel interview with a role-based question map, concise example answers, conflicting-priority scenarios, and a structured practice routine.",
  "A panel interview brings several perspectives into one conversation. Prepare to explain the same work at different levels of detail while keeping your own contribution clear.",
  "job-interview-questions-and-answers",[["https://nationalcareers.service.gov.uk/careers-advice/interview-advice","National Careers Service: interview preparation"]],[
  ["What should you find out before the panel?","Confirm the duration, format, participants if available, and whether a presentation or exercise is expected. Use the role description to identify the evidence you want to demonstrate. A panel can include technical, managerial, and cross-functional perspectives, but do not assume a fixed format for every employer.\n\nBuild a small evidence map: one project decision, one collaboration example, and one setback. Each example should have a clear personal contribution and an outcome you can honestly discuss. Reusing a strong example with a different emphasis is better than inventing a new story for every question."],
  ["How do you answer several people without rambling?","Answer the question asked first, then give enough context for the whole panel to follow. In a video interview, keep names and roles in a simple note if permitted. Acknowledge the questioner while remaining conversational with the group.\n\nFor 'Why did you choose that design?', start with the requirement and decision. Add the tradeoff and result. If a specialist asks for implementation detail, expand that part rather than restarting your entire project story. A layered answer lets different listeners find the information they need."],
  ["What if panel members ask about conflicting priorities?","Make the conflict explicit and explain your decision criteria. For example, a product lead wants a faster release while an engineer asks about reliability. Clarify the acceptable risk, reversibility, and evidence needed to choose a path. Avoid simply agreeing with whichever person spoke last.\n\nAn original practice response is: 'I would separate the reversible UI change from the migration, release the smaller change first, and use the migration checks to decide the second release.' Adapt the reasoning to a real situation rather than presenting this fictional example as your experience."],
  ["How should you handle a question you do not understand?","Ask a brief clarifying question and restate the problem. If you lack a fact, say what you know and describe how you would investigate the missing part. Several interviewers being present does not require an immediate guess.\n\nIf two questions arrive together, identify both and answer them in order. Keep the first answer concise enough to leave time for the second. At the end, check whether you addressed the intended concern without repeatedly seeking reassurance after every sentence."],
],"Run a twenty-minute mock with three perspectives: a hiring manager, a technical colleague, and a partner team. Use one project and give each perspective a different follow-up. Record where you repeat background unnecessarily or lose the original question.\n\nFinish with two questions of your own: how the team defines success for the role and where collaboration commonly becomes difficult. Score relevance, evidence, brevity, and handling of follow-ups. The score is a practice aid, not a hiring prediction.","Enter the panel roles and your project notes into Cluegent for preparation, then ask it to alternate perspectives. Practise answering the same decision in a concise business version and a deeper technical version.");

add("explain-career-gap-interview","How to Explain a Career Gap in an Interview",
  "Prepare a clear career-gap interview answer with original examples for caregiving, job search, and study, plus a concise readiness-focused practice framework.",
  "A career-gap answer works best when it gives an accurate timeline, a brief explanation, and relevant evidence of readiness. You do not need to invent achievements to account for every month.",
  "resume-based-interview-questions-and-answers",[["https://nationalcareers.service.gov.uk/careers-advice/interview-advice","National Careers Service: preparing interview answers"]],[
  ["What should a short career-gap answer contain?","Name the period, explain the reason at a level you are comfortable sharing, and connect the conversation to your readiness for this role. Keep dates consistent with your application. Avoid turning a straightforward timeline question into a long defensive speech.\n\nAn answer can be honest even when the break was not spent collecting certifications. The interviewer still needs evidence that you can do the work now. Choose a relevant project, previous accomplishment, or recent practice result that you can discuss in detail."],
  ["How might you explain a caregiving break?","Here is an original fictional example: 'I stepped away from full-time work to handle family caregiving responsibilities. I am now available for the schedule this role requires, and I have been refreshing my SQL and reporting skills through a small project I can walk you through.'\n\nOnly use the parts that are true for you. Do not claim that a responsibility has ended if it has not. You can discuss current availability without providing intimate personal details. Keep the transition from the reason to readiness natural rather than rushing through the question."],
  ["How do you explain a longer job search?","Describe the period accurately and focus on what you learned about your target role. If you completed relevant work, mention a specific example. If you did not, use evidence from prior experience and explain your current preparation without exaggeration.\n\nA fictional example is: 'My role ended, and my search took longer than expected. I narrowed my focus to backend positions and built a small API project to refresh deployment and testing. I can explain the tradeoffs and the parts I would improve.' This is a structure to adapt, not a script to copy as fact."],
  ["What follow-up questions should you prepare for?","Expect possible questions about your availability, relevant skills, and why this opportunity fits your next step. Prepare concrete evidence for each. A certificate name alone does not show that you can apply a concept; a clear explanation of a small completed exercise can be more informative.\n\nKeep your answer consistent across the resume, application, and conversation. If dates are approximate, clarify them. Avoid inventing freelance clients or describing practice work as paid employment. A credible explanation should remain easy to defend when someone asks one level deeper."],
],"Write a three-sentence answer: timeline, reason, and readiness. Read it aloud and remove details that do not help the listener understand those three points. Then prepare one real example supporting your readiness.\n\nAsk a practice partner to follow up with 'What have you refreshed recently?' and 'Why this role now?' Answer without expanding the story beyond what happened. The goal is a calm, accurate explanation that lets the interview return to your capabilities.","Use Cluegent to review the clarity of a career-gap answer you have written from your own experience. Ask it to shorten the wording while preserving the facts and your preferred level of personal detail.");

add("hiring-manager-interview-questions","Hiring Manager Interview Questions and Strong Answer Examples",
  "Prepare for a hiring manager interview with questions on ownership, priorities, feedback, and first-month plans, plus original answer structures and follow-ups.",
  "A hiring manager conversation often explores how you will contribute to the team's actual work. Prepare evidence of judgment, collaboration, and ownership alongside your technical skills.",
  "software-engineer-behavioral-interview-questions",[["https://nationalcareers.service.gov.uk/careers-advice/interview-advice","National Careers Service: interview preparation and examples"]],[
  ["Why are you interested in this particular role?","Connect a real requirement in the job description to relevant experience and a specific reason the work interests you. Avoid relying entirely on praise for the company's reputation. A convincing answer explains the contribution you can make and the area you want to develop.\n\nFor a backend role focused on reliability, discuss a system you maintained and the operating problem you found engaging. Distinguish what you have already done from what you hope to learn. That makes it easier for the manager to assess both fit and development needs."],
  ["Tell me about something you owned end to end", "Explain the problem, your authority, the decisions you made, and how the outcome was evaluated. Ownership can include asking for help and coordinating with others. Do not describe the whole team's delivery as solely your achievement.\n\nUse a real example with a visible tradeoff: reducing scope to meet a deadline, adding a rollout check, or changing a design after feedback. State what you personally did and what others contributed. If the result was mixed, explain the limitation and the next action rather than inventing a perfect ending."],
  ["How do you handle competing priorities?","Clarify business impact, urgency, dependencies, and the cost of delay. Communicate the tradeoff to the people who own the priorities. A useful answer includes how you handle a new urgent request after work has already started.\n\nOur fictional example has a customer incident, a planned feature, and a cleanup task. Stabilize the incident according to its impact, explain the feature's revised timeline, and reschedule cleanup with visible ownership. Change the incident to a low-impact issue and reconsider: the priority should follow evidence, not a memorized ordering."],
  ["What would you do in your first month?","Start with learning the team's goals, customer problems, system boundaries, and delivery process. Identify a small useful contribution and the people needed to validate it. Avoid promising a rewrite or a fixed business result before understanding the environment.\n\nA strong answer proposes observable milestones: understand one critical workflow, ship a bounded change with review, and agree on the next priority with the manager. Ask how success is evaluated in the role. Your plan should invite alignment instead of implying that you already know every problem."],
],"Choose three real stories covering ownership, feedback, and a difficult priority decision. For each, write your action, supporting evidence, and one thing you would change. Practise a ninety-second version and a deeper follow-up.\n\nEnd the mock by asking what success looks like after three months and which problem needs attention first. Use the answers to refine your understanding of the role. A hiring manager interview is also a chance to assess whether the work and expectations suit you.","Give Cluegent the public job description and a brief factual project summary during preparation. Ask for hiring-manager follow-ups about ownership and tradeoffs, then practise responding without adding unsupported achievements.");

